// cl /O2 /std:c++17 /EHsc bench\solve_test11_order.cpp /Fe:target\solve_test11_order.exe
// Input domains are generated by target/dag_data11.py from the locked prefix.
#include <algorithm>
#include <atomic>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iostream>
#include <mutex>
#include <numeric>
#include <random>
#include <string>
#include <thread>
#include <vector>
using namespace std;
struct Pipe { int id,s,e,l,base; vector<pair<int,int>> dom; };
struct Tree {
 static constexpr int N=16384;
 vector<int> mx,lazy;
 Tree():mx(2*N),lazy(2*N,-1){}
 void clear(){fill(mx.begin(),mx.end(),0);fill(lazy.begin(),lazy.end(),-1);}
 void push(int v){if(lazy[v]>=0){mx[v*2]=mx[v*2+1]=lazy[v];lazy[v*2]=lazy[v*2+1]=lazy[v];lazy[v]=-1;}}
 int query(int v,int l,int r,int a,int b){if(a<=l&&r<=b)return mx[v];push(v);int m=(l+r)/2,x=0;if(a<m)x=query(v*2,l,m,a,b);if(b>m)x=max(x,query(v*2+1,m,r,a,b));return x;}
 void set(int v,int l,int r,int a,int b,int z){if(a<=l&&r<=b){mx[v]=lazy[v]=z;return;}push(v);int m=(l+r)/2;if(a<m)set(v*2,l,m,a,b,z);if(b>m)set(v*2+1,m,r,a,b,z);mx[v]=max(mx[v*2],mx[v*2+1]);}
};
int main(int argc,char**argv){
 int seconds=argc>1?stoi(argv[1]):300,threads=argc>2?stoi(argv[2]):16;
 ifstream in("target/test11-dag-data.txt");int n,T;in>>n>>T;vector<Pipe>p(n);
 for(auto &q:p){int k;in>>q.id>>q.s>>q.e>>q.l>>q.base>>k;q.dom.resize(k);for(auto &v:q.dom)in>>v.first>>v.second;}
 vector<int>initial(n);iota(initial.begin(),initial.end(),0);sort(initial.begin(),initial.end(),[&](int a,int b){return p[a].base<p[b].base;});
 atomic<int>best(30000);atomic<bool>done(false);mutex lock;vector<int>bestorder=initial,bestpos;
 auto start=chrono::steady_clock::now();
 auto worker=[&](int tid){
  mt19937 rng(7717+tid*11117);uniform_real_distribution<double>u(0,1);Tree tr;vector<int>pos(n),order=initial,trial;
  auto evaluate=[&](const vector<int>&perm){
   tr.clear();int height=0;long long over=0,late=0;
   for(int i:perm){int lb=tr.query(1,0,Tree::N,p[i].s,p[i].e),z=30000;
    for(auto [a,b]:p[i].dom)if(b>=lb){z=max(a,lb);break;}
    pos[i]=z;int top=z+p[i].l;tr.set(1,0,Tree::N,p[i].s,p[i].e,top);height=max(height,top);
    if(top>20760)over+=top-20760;
    if(p[i].s<=9818&&9818<p[i].e)late+=z;
   }
   return pair<int,double>{height,height+over*.001+late*.00000001};
  };
  auto cur=evaluate(order);double value=cur.second;int local=cur.first;long long steps=0,accepted=0;
  while(!done.load()){
   double elapsed=chrono::duration<double>(chrono::steady_clock::now()-start).count();if(elapsed>seconds)break;
   if(cur.first<best.load()){
    lock_guard<mutex>g(lock);
    if(cur.first<best){best=cur.first;bestorder=order;bestpos=pos;cout<<"BEST "<<cur.first<<" thread "<<tid<<" t "<<elapsed<<" steps "<<steps<<endl;
     vector<int>out;ifstream b("target/test11-resume.txt");int z;while(b>>z)out.push_back(z);for(int i=0;i<n;i++)out[p[i].id]=pos[i];ofstream f("target/test11-order-search.txt");for(int z:out)f<<z<<'\n';
     if(cur.first<=20760)done=true;
    }
   }
   trial=order;int a=rng()%n,b=a;int kind=rng()%10;
   if(kind<7){
    if(kind<2){vector<int>critical;for(int q=0;q<n;q++){int i=order[q];if(pos[i]>=20361&&p[i].e>9700)critical.push_back(q);}if(!critical.empty())a=critical[rng()%critical.size()];}
    int span=kind<4?4:kind<6?24:120;b=max(0,min(n-1,a+int(rng()%(2*span+1))-span));swap(trial[a],trial[b]);
   }
   else {
    // Cross-slot exchanges act on live peak pipes, including distant ends of
    // the trench. They are essential when every local gap is shorter than 8.
    if(kind==9){
     vector<int>peak,high;for(int q=0;q<n;q++){int i=order[q];if(p[i].s<=9818&&9818<p[i].e){peak.push_back(q);if(pos[i]>=20361)high.push_back(q);}}
     if(!high.empty())a=high[rng()%high.size()];
     if(!peak.empty())b=peak[rng()%peak.size()];
     swap(trial[a],trial[b]);
     if(rng()%2){
      int aa=rng()%n,bb=aa;int id=order[aa];
      vector<int>same;for(int q:peak)if(abs(p[order[q]].l-p[id].l)<=3)same.push_back(q);
      if(!same.empty()){bb=same[rng()%same.size()];swap(trial[aa],trial[bb]);}
     }
    }else{b=rng()%n;int v=trial[a];trial.erase(trial.begin()+a);trial.insert(trial.begin()+b,v);}
   }
   auto candidate=evaluate(trial);steps++;
   if(steps%5000==0&&tid==0)cout<<"PROBE "<<candidate.first<<" mode "<<kind<<endl;
   double phase=fmod(double(steps),5000)/5000;
   double temperature=(tid%4==0?.1:tid%4==1?2.0:tid%4==2?10.0:40.0)*(1-phase)+.002;
   if(candidate.second<=value||u(rng)<exp((value-candidate.second)/temperature)){
    order.swap(trial);cur=candidate;value=cur.second;accepted++;
   }else{
    // Restore the current positions before checking/saving the next incumbent.
    cur=evaluate(order);
   }
   if(steps%5000==0){lock_guard<mutex>g(lock);if(tid==0)cout<<"STEP "<<steps<<" local "<<cur.first<<" accepted "<<accepted<<" global "<<best<<endl;if(cur.first>best+80||u(rng)<.15){order=bestorder;cur=evaluate(order);value=cur.second;}}
  }
 };
 vector<thread>pool;for(int i=0;i<threads;i++)pool.emplace_back(worker,i);for(auto&t:pool)t.join();cout<<"FINISHED "<<best<<endl;
}
